Here is the commit message:
netrom: fix double-free in nr_route_frame()

In nr_route_frame(), old_skb is immediately freed without checking if
nr_neigh->ax25 pointer is NULL. Therefore, if nr_neigh->ax25 is NULL,
the caller function will free old_skb again, causing a double-free bug.

Therefore, to prevent this, we need to modify it to check whether
nr_neigh->ax25 is NULL before freeing old_skb.

Cc: <stable@vger.kernel.org>
Reported-by: syzbot+999115c3bf275797dc27@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/all/69694d6f.050a0220.58bed.0029.GAE@google.com/
Fixes: 1da177e4c3f4 ("Linux-2.6.12-rc2")
Signed-off-by: Jeongjun Park <aha310510@gmail.com>
Link: https://patch.msgid.link/20260119063359.10604-1-aha310510@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In nr_route_frame(), the original skb (passed as argument) was immediately freed after making an expanded copy, regardless of the transmission outcome. However, if nr_neigh->ax25 is NULL, the function returns a non-zero value that causes the caller to also free the same skb, resulting in a double-free. The fix defers freeing the original skb until after the transmission result is known, freeing it only when the frame is successfully transmitted (ret non-zero), thus preventing the double-free.

Here is the patch:
  */
 int nr_route_frame(struct sk_buff *skb, ax25_cb *ax25)
 {
 	ax25_address *nr_src, *nr_dest;
 	struct nr_neigh *nr_neigh;
 	struct nr_node  *nr_node;
 	struct net_device *dev;
 	unsigned char *dptr;
 	ax25_cb *ax25s;
 	int ret;
-	struct sk_buff *skbn;
+	struct sk_buff *nskb, *oskb;

 	/*
 	 * Reject malformed packets early. Check that it contains at least 2
 	 * addresses and 1 byte more for Time-To-Live
 	 */
 	if (skb->len < 2 * sizeof(ax25_address) + 1)
 		return 0;

 	nr_src  = (ax25_address *)(skb->data + 0);
 	nr_dest = (ax25_address *)(skb->data + 7);

 	if (ax25 != NULL) {
 		ret = nr_add_node(nr_src, "", &ax25->dest_addr, ax25->digipeat,
 				  ax25->ax25_dev->dev, 0,
 				  READ_ONCE(sysctl_netrom_obsolescence_count_initialiser));
 		if (ret)
 			return ret;
 	}

 	if ((dev = nr_dev_get(nr_dest)) != NULL) {	/* Its for me */
 		if (ax25 == NULL)			/* Its from me */
 			ret = nr_loopback_queue(skb);
 		else
 			ret = nr_rx_frame(skb, dev);
 		dev_put(dev);
 		return ret;
 	}

 	if (!READ_ONCE(sysctl_netrom_routing_control) && ax25 != NULL)
 		return 0;

 	/* Its Time-To-Live has expired */
 	if (skb->data[14] == 1) {
 		return 0;
 	}

 	nr_node = nr_node_get(nr_dest);
 	if (nr_node == NULL)
 		return 0;
 	nr_node_lock(nr_node);

 	if (nr_node->which >= nr_node->count) {
 		nr_node_unlock(nr_node);
 		nr_node_put(nr_node);
 		return 0;
 	}

 	nr_neigh = nr_node->routes[nr_node->which].neighbour;

 	if ((dev = nr_dev_first()) == NULL) {
 		nr_node_unlock(nr_node);
 		nr_node_put(nr_node);
 		return 0;
 	}

 	/* We are going to change the netrom headers so we should get our
 	   own skb, we also did not know until now how much header space
 	   we had to reserve... - RXQ */
-	if ((skbn=skb_copy_expand(skb, dev->hard_header_len, 0, GFP_ATOMIC)) == NULL) {
+	nskb = skb_copy_expand(skb, dev->hard_header_len, 0, GFP_ATOMIC);
+
+	if (!nskb) {
 		nr_node_unlock(nr_node);
 		nr_node_put(nr_node);
 		dev_put(dev);
 		return 0;
 	}
-	kfree_skb(skb);
-	skb=skbn;
+	oskb = skb;
+	skb = nskb;
 	skb->data[14]--;

 	dptr  = skb_push(skb, 1);
 	*dptr = AX25_P_NETROM;

 	ax25s = nr_neigh->ax25;
 	nr_neigh->ax25 = ax25_send_frame(skb, 256,
 					 (const ax25_address *)dev->dev_addr,
 					 &nr_neigh->callsign,
 					 nr_neigh->digipeat, nr_neigh->dev);
 	if (ax25s)
 		ax25_cb_put(ax25s);

 	dev_put(dev);
 	ret = (nr_neigh->ax25 != NULL);
 	nr_node_unlock(nr_node);
 	nr_node_put(nr_node);

+	if (ret)
+		kfree_skb(oskb);
+
 	return ret;
 }



